    const scanTable=tableShell('<tr><th>Scan</th><th>Points</th><th>Voltage span</th><th>Current span</th><th>Direction changes</th><th>Duplicate V</th><th>Status</th></tr>','<tr><td>FW</td><td>'+fw.n+'</td><td>'+((fw.n)?C.fmt(fw.vmin,3)+' → '+C.fmt(fw.vmax,3)+' V':'—')+'</td><td>'+((fw.n)?C.fmt(fw.jmin,2)+' → '+C.fmt(fw.jmax,2):'—')+'</td><td>'+fw.reversals+'</td><td>'+fw.duplicates+'</td><td>'+diagnosticStatus(fw)+'</td></tr><tr><td>RV</td><td>'+rv.n+'</td><td>'+((rv.n)?C.fmt(rv.vmin,3)+' → '+C.fmt(rv.vmax,3)+' V':'—')+'</td><td>'+((rv.n)?C.fmt(rv.jmin,2)+' → '+C.fmt(rv.jmax,2):'—')+'</td><td>'+rv.reversals+'</td><td>'+rv.duplicates+'</td><td>'+diagnosticStatus(rv)+'</td></tr>','dense-table stack-table jv-integrity-table');
    const separation=sep?'<div class="jv-separation"><div><span>Overlap</span><strong>'+C.fmt(sep.lo,3)+' → '+C.fmt(sep.hi,3)+' V</strong></div><div><span>Mean |ΔJ|</span><strong>'+C.fmt(sep.meanAbs,3)+'</strong></div><div><span>RMS ΔJ</span><strong>'+C.fmt(sep.rms,3)+'</strong></div><small>Descriptive separation across '+sep.samples+' interpolated voltage points.</small></div>':'<div class="jv-separation empty"><span>FW/RV separation</span><strong>Not available</strong><small>Both scans need an overlapping voltage range.</small></div>';
    const deltas='<div class="jv-diagnostic-grid">'+analyzerMetric('ΔPCE RV−FW',signed(deltaEff,2,'%'),'deterministic scan summary')+analyzerMetric('ΔVoc RV−FW',signed(deltaVoc,3,' V'),'scan-to-scan delta')+analyzerMetric('ΔJsc RV−FW',signed(deltaJsc,2,''),'mismatch-adjusted delta')+analyzerMetric('ΔFF RV−FW',signed(deltaFf,3,''),'scan-to-scan delta')+'</div>';
