  function renderBody(e){const tab=S.state.ui.resultsTab||'overview';if(tab==='overview')return overview(e);if(['all','measurements','best','anomalies','top','topref'].includes(tab))return dataWorkbench(e);if(['curves','overlay'].includes(tab))return jvWorkbench(e);if(tab==='boxplots')return compare(e);return overview(e);}
  function analysisSettings(){return '<details class="panel results-analysis-settings"><summary class="panel-head"><div><strong>Analysis settings</strong><div class="meta">Advanced normalization controls · current mismatch '+C.fmt(factor(),2)+'×</div></div></summary><div class="panel-body"><label class="field results-mismatch-field"><span class="field-label">Mismatch factor</span><input class="input mismatch-input" id="resultMismatchFactor" type="number" min="0.01" step="0.01" value="'+factor()+'"><small class="help">Changes deterministic analysis values; leave at 1.00 unless your measurement workflow requires a correction.</small></label></div></details>';}
  function interpretationPanel(annotation){if(!annotation)return'';if(annotation.markdown)return '<section class="panel ai-result-panel"><div class="panel-head"><h2 class="h2">AI interpretation</h2>'+badge('derived','ai')+'</div><div class="panel-body markdown-view">'+C.markdown(annotation.markdown)+'</div></section>';const data=annotation.data||annotation;if(!data||typeof data!=='object')return'';let md='';if(data.summary)md+='## Summary\n\n'+String(data.summary)+'\n\n';if(Array.isArray(data.observations)&&data.observations.length){md+='## Observations\n\n'+data.observations.map(function(x){return '- '+String(x.statement||x);}).join('\n')+'\n\n';}if(Array.isArray(data.hypotheses)&&data.hypotheses.length){md+='## Hypotheses\n\n'+data.hypotheses.map(function(x){return '- '+String(x.statement||x);}).join('\n')+'\n\n';}if(Array.isArray(data.limitations)&&data.limitations.length)md+='## Limitations\n\n'+data.limitations.map(function(x){return '- '+String(x);}).join('\n')+'\n\n';if(Array.isArray(data.next_checks)&&data.next_checks.length)md+='## Next checks\n\n'+data.next_checks.map(function(x){return '- '+String(x);}).join('\n');return md?'<section class="panel ai-result-panel"><div class="panel-head"><h2 class="h2">AI interpretation</h2>'+badge('derived','ai')+'</div><div class="panel-body markdown-view">'+C.markdown(md)+'</div></section>':'';}
  function render(){if(!hasExperiment())return needExperiment();const e=exp();if(!e.analysis||!e.analysis.summary)LF.Analysis.analyze(e);const main=resultsMainTab();if(LF.PageContext)LF.PageContext.publish('Results',{view:main==='compare'?'Compare':main==='jv'?'JV workspace':main==='data'?'Data explorer':'Overview',selected:{measurement:S.state.ui.selectedMeasurementId||'',groups:(S.state.ui.boxPlot&&S.state.ui.boxPlot.groups||[]).slice()},filters:{dataMode:dataMode(),jvMode:jvMode(),metric:S.state.ui.boxPlot&&S.state.ui.boxPlot.metric||'',direction:S.state.ui.boxPlot&&S.state.ui.boxPlot.direction||'',eligibleOnly:S.state.ui.boxPlot&&S.state.ui.boxPlot.eligibleOnly!==false},visible:['measurements:'+e.measurements.length]});const interpretation=LF.ActionData&&LF.ActionData.annotation(e,'results.interpret'),interp=main==='overview'?interpretationPanel(interpretation):'';return '<section class="page results-page">'+workflowHead('Results','Triage performance, inspect outliers and compare groups without rebuilding the analysis.','<button class="button primary" data-action="results.interpret">Interpret with AI</button>')+tabs()+(main==='overview'?analysisSettings():'')+interp+renderBody(e)+'</section>';}

  function renderResultInspector(){const shade=document.getElementById('resultInspectorShade'),body=document.getElementById('resultInspectorBody');if(!shade||!body)return;const e=exp(),m=hasExperiment()&&S.state.ui.resultInspectorId&&e.measurements.find(function(x){return x.id===S.state.ui.resultInspectorId;});if(!m){shade.hidden=true;return;}if(LF.PageContext)LF.PageContext.publish('Results',{view:'Measurement inspector',selected:{measurement:m.id,sample:m.sample||''},visible:['curve','warnings','source']});shade.hidden=false;document.getElementById('resultInspectorTitle').textContent=m.sample||'Measurement';document.getElementById('resultInspectorSubtitle').textContent=(m.group||'')+' · '+(m.file||'');body.innerHTML=resultInspectorHtml(m);}
