    if(kind==='curve'){const direction=S.state.ui.curveDirection||'both',rows=[];curveExportMeasurements(e).forEach(function(m){['fw','rv'].forEach(function(d){if(direction!=='both'&&direction!==d)return;((m.curve||{})[d]||[]).forEach(function(p,i){const x=Number(p.x),y=Number(p.y);if(Number.isFinite(x)&&Number.isFinite(y))rows.push({sample:m.sample,experiment:groupName(m),scan:d.toUpperCase(),point:i+1,voltage_v:x,current_density_mA_cm2:y/f});});});});return rows;}
