    if(kind==='group'){const key=S.state.ui.resultsOverviewMetric||'eff',direction=key==='hysteresis'?'best':(S.state.ui.resultsOverviewDirection||'best'),meta=overviewMetricMeta(key),stat=S.state.ui.resultsOverviewStatistic||'median';return groupSummaryRows(e).sort(function(a,b){return (stat==='mean'?b.mean:b.median)-(stat==='mean'?a.mean:a.median);}).map(function(g){return{experiment:g.name,metric:meta.label,scan:direction,statistic:stat,n:g.n,value:stat==='mean'?g.mean:g.median,mean:g.mean,median:g.median,q1:g.q1,q3:g.q3,min:g.min,max:g.max};});}
